class DiscGeometry extends Geometry {
  constructor(steps = 4, radius = 1) {
    super();
    steps = Math.max(4, steps);

    const alpha = (2 * Math.PI) / steps;

    this.addVertex(0, 0, 0);
    this.lastVertex.uv[0] = 0.5;
    this.lastVertex.uv[1] = 0.5;

    for (let i = 0; i < steps; ++i) {
      const x = Math.cos(alpha * i);
      const y = Math.sin(alpha * i);
      this.addVertex(radius * x, radius * y, 0);
      this.lastVertex.uv[0] = x * 0.5 + 0.5;
      this.lastVertex.uv[1] = y * 0.5 + 0.5;

      if (i > 0) {
        this.addFace(0, i, i + 1);
      }
    }
    this.addFace(0, steps, 1);
  }
}

function createShader(gl, type, source) {
  const shader = gl.createShader(type);
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  const success = gl.getShaderParameter(shader, gl.COMPILE_STATUS);

  if (success) {
    return shader;
  }

  console.error(gl.getShaderInfoLog(shader));
  gl.deleteShader(shader);
  return null;
}

function createProgram(
  gl,
  shaderSources,
  transformFeedbackVaryings,
  attribLocations
) {
  const program = gl.createProgram();

  [gl.VERTEX_SHADER, gl.FRAGMENT_SHADER].forEach((type, ndx) => {
    const shader = createShader(gl, type, shaderSources[ndx]);
    if (shader) gl.attachShader(program, shader);
  });

  if (transformFeedbackVaryings) {
    gl.transformFeedbackVaryings(
      program,
      transformFeedbackVaryings,
      gl.SEPARATE_ATTRIBS
    );
  }

  if (attribLocations) {
    for (const attrib in attribLocations) {
      gl.bindAttribLocation(program, attribLocations[attrib], attrib);
    }
  }

  gl.linkProgram(program);
  const success = gl.getProgramParameter(program, gl.LINK_STATUS);

  if (success) {
    return program;
  }

  console.error(gl.getProgramInfoLog(program));
  gl.deleteProgram(program);
  return null;
}

function makeVertexArray(gl, bufLocNumElmPairs, indices) {
  const va = gl.createVertexArray();
  gl.bindVertexArray(va);

  for (const [buffer, loc, numElem] of bufLocNumElmPairs) {
    if (loc === -1) continue;
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
    gl.enableVertexAttribArray(loc);
    gl.vertexAttribPointer(loc, numElem, gl.FLOAT, false, 0, 0);
  }

  if (indices) {
    const indexBuffer = gl.createBuffer();
    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, indexBuffer);
    gl.bufferData(
      gl.ELEMENT_ARRAY_BUFFER,
      new Uint16Array(indices),
      gl.STATIC_DRAW
    );
  }

  gl.bindVertexArray(null);
  return va;
}

function resizeCanvasToDisplaySize(canvas) {
  const dpr = Math.min(2, Math.max(1, window.devicePixelRatio || 1));
  const displayWidth = Math.round((canvas.clientWidth || 300) * dpr);
  const displayHeight = Math.round((canvas.clientHeight || 300) * dpr);
  const needResize =
    canvas.width !== displayWidth || canvas.height !== displayHeight;
  if (needResize) {
    canvas.width = displayWidth;
    canvas.height = displayHeight;
  }
  return needResize;
}

function makeBuffer(gl, sizeOrData, usage) {
  const buf = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buf);
  gl.bufferData(gl.ARRAY_BUFFER, sizeOrData, usage);
  gl.bindBuffer(gl.ARRAY_BUFFER, null);
  return buf;
}

function createAndSetupTexture(gl, minFilter, magFilter, wrapS, wrapT) {
  const texture = gl.createTexture();
  gl.bindTexture(gl.TEXTURE_2D, texture);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, wrapS);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, wrapT);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, minFilter);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, magFilter);
  return texture;
}

class ArcballControl {
  isPointerDown = false;
  orientation = quat.create();
  pointerRotation = quat.create();
  rotationVelocity = 0;
  rotationAxis = vec3.fromValues(1, 0, 0);
  snapDirection = vec3.fromValues(0, 0, -1);
  snapTargetDirection;
  EPSILON = 0.1;
  IDENTITY_QUAT = quat.create();

  #getCanvasPoint(e) {
    const rect = this.canvas.getBoundingClientRect();
    return vec2.fromValues(
      Math.max(0, Math.min(rect.width, e.clientX - rect.left)),
      Math.max(0, Math.min(rect.height, e.clientY - rect.top))
    );
  }

  constructor(canvas, updateCallback) {
    this.canvas = canvas;
    this.updateCallback = updateCallback || (() => null);

    this.pointerPos = vec2.create();
    this.previousPointerPos = vec2.create();
    this._rotationVelocity = 0;
    this._combinedQuat = quat.create();

    this.boundPointerDown = (e) => {
      const p = this.#getCanvasPoint(e);
      vec2.copy(this.pointerPos, p);
      vec2.copy(this.previousPointerPos, p);
      this.isPointerDown = true;
      if (
        this.canvas &&
        typeof this.canvas.setPointerCapture === 'function' &&
        e.pointerId != null
      ) {
        try {
          this.canvas.setPointerCapture(e.pointerId);
        } catch {
          // Ignored: pointer capture may fail if pointer is no longer active
        }
      }
    };
    this.boundPointerUp = (e) => {
      this.isPointerDown = false;
      if (
        this.canvas &&
        typeof this.canvas.releasePointerCapture === 'function' &&
        e?.pointerId != null
      ) {
        try {
          if (this.canvas.hasPointerCapture(e.pointerId)) {
            this.canvas.releasePointerCapture(e.pointerId);
          }
        } catch {
          // Ignored: release pointer capture can fail if already released
        }
      }
    };
    this.boundPointerCancel = (e) => {
      this.isPointerDown = false;
      if (
        this.canvas &&
        typeof this.canvas.releasePointerCapture === 'function' &&
        e?.pointerId != null
      ) {
        try {
          if (this.canvas.hasPointerCapture(e.pointerId)) {
            this.canvas.releasePointerCapture(e.pointerId);
          }
        } catch {
          // Ignored: release pointer capture can fail if already released
        }
      }
    };
    this.boundPointerLeave = (e) => {
      if (
        e?.pointerId != null &&
        this.canvas &&
        typeof this.canvas.hasPointerCapture === 'function'
      ) {
        try {
          if (!this.canvas.hasPointerCapture(e.pointerId)) {
            this.isPointerDown = false;
          }
        } catch {
          this.isPointerDown = false;
        }
      } else {
        this.isPointerDown = false;
      }
    };
    this.boundPointerMove = (e) => {
      if (this.isPointerDown) {
        const p = this.#getCanvasPoint(e);
        vec2.copy(this.pointerPos, p);
      }
    };

    canvas.addEventListener('pointerdown', this.boundPointerDown);
    canvas.addEventListener('pointerup', this.boundPointerUp);
    canvas.addEventListener('pointercancel', this.boundPointerCancel);
    canvas.addEventListener('pointerleave', this.boundPointerLeave);
    canvas.addEventListener('pointermove', this.boundPointerMove);

    canvas.style.touchAction = 'pan-y';
  }

  destroy() {
    if (this.canvas) {
      this.canvas.removeEventListener('pointerdown', this.boundPointerDown);
      this.canvas.removeEventListener('pointerup', this.boundPointerUp);
      this.canvas.removeEventListener('pointercancel', this.boundPointerCancel);
      this.canvas.removeEventListener('pointerleave', this.boundPointerLeave);
      this.canvas.removeEventListener('pointermove', this.boundPointerMove);
    }
  }

  update(deltaTime, targetFrameDuration = 16) {
    const timeScale = deltaTime / targetFrameDuration + 0.00001;
    let angleFactor = timeScale;
    let snapRotation = quat.create();

    if (this.isPointerDown) {
      const INTENSITY = 0.3 * timeScale;
      const ANGLE_AMPLIFICATION = 5 / timeScale;

      const midPointerPos = vec2.sub(
        vec2.create(),
        this.pointerPos,
        this.previousPointerPos
      );
      vec2.scale(midPointerPos, midPointerPos, INTENSITY);

      if (vec2.sqrLen(midPointerPos) > this.EPSILON) {
        vec2.add(midPointerPos, this.previousPointerPos, midPointerPos);

        const p = this.#project(midPointerPos);
        const q = this.#project(this.previousPointerPos);
        const a = vec3.normalize(vec3.create(), p);
        const b = vec3.normalize(vec3.create(), q);

        vec2.copy(this.previousPointerPos, midPointerPos);

        angleFactor *= ANGLE_AMPLIFICATION;

        this.quatFromVectors(a, b, this.pointerRotation, angleFactor);
      } else {
        quat.slerp(
          this.pointerRotation,
          this.pointerRotation,
          this.IDENTITY_QUAT,
          INTENSITY
        );
      }
    } else {
      const INTENSITY = 0.1 * timeScale;
      quat.slerp(
        this.pointerRotation,
        this.pointerRotation,
        this.IDENTITY_QUAT,
        INTENSITY
      );

      if (this.snapTargetDirection) {
        const SNAPPING_INTENSITY = 0.2;
        const a = this.snapTargetDirection;
        const b = this.snapDirection;
        const sqrDist = vec3.squaredDistance(a, b);
        const distanceFactor = Math.max(0.1, 1 - sqrDist * 10);
        angleFactor *= SNAPPING_INTENSITY * distanceFactor;
        this.quatFromVectors(a, b, snapRotation, angleFactor);
      }
    }

    const combinedQuat = quat.multiply(
      quat.create(),
      snapRotation,
      this.pointerRotation
    );
    this.orientation = quat.multiply(
      quat.create(),
      combinedQuat,
      this.orientation
    );
    quat.normalize(this.orientation, this.orientation);

    const RA_INTENSITY = 0.8 * timeScale;
    quat.slerp(
      this._combinedQuat,
      this._combinedQuat,
      combinedQuat,
      RA_INTENSITY
    );
    quat.normalize(this._combinedQuat, this._combinedQuat);

    const rad = Math.acos(this._combinedQuat[3]) * 2.0;
    const s = Math.sin(rad / 2.0);
    let rv = 0;
    if (s > 0.000001) {
      rv = rad / (2 * Math.PI);
      this.rotationAxis[0] = this._combinedQuat[0] / s;
      this.rotationAxis[1] = this._combinedQuat[1] / s;
      this.rotationAxis[2] = this._combinedQuat[2] / s;
    }

    const RV_INTENSITY = 0.5 * timeScale;
    this._rotationVelocity += (rv - this._rotationVelocity) * RV_INTENSITY;
    this.rotationVelocity = this._rotationVelocity / timeScale;

    this.updateCallback(deltaTime);
  }

  quatFromVectors(a, b, out, angleFactor = 1) {
    const axis = vec3.cross(vec3.create(), a, b);
    vec3.normalize(axis, axis);
    const d = Math.max(-1, Math.min(1, vec3.dot(a, b)));
    const angle = Math.acos(d) * angleFactor;
    quat.setAxisAngle(out, axis, angle);
    return { q: out, axis, angle };
  }

  #project(pos) {
    const r = 2;
    const w = this.canvas.clientWidth || 300;
    const h = this.canvas.clientHeight || 300;
    const s = Math.max(w, h, 1) - 1 || 1;

    const x = (2 * pos[0] - w - 1) / s;
    const y = (2 * pos[1] - h - 1) / s;
    let z = 0;
    const xySq = x * x + y * y;
    const rSq = r * r;

    if (xySq <= rSq / 2.0) {
      z = Math.sqrt(Math.max(0, rSq - xySq));
    } else {
      z = rSq / Math.sqrt(Math.max(0.0001, xySq));
    }
    return vec3.fromValues(-x, y, z);
  }
}

class InfiniteGridMenu {
  TARGET_FRAME_DURATION = 1000 / 60;
  SPHERE_RADIUS = 2;

  #time = 0;
  #deltaTime = 0;
  #deltaFrames = 0;
  #frames = 0;

  camera = {
    matrix: mat4.create(),
    near: 0.1,
    far: 40,
    fov: Math.PI / 4,
    aspect: 1,
    position: vec3.fromValues(0, 0, 3),
    up: vec3.fromValues(0, 1, 0),
    matrices: {
      view: mat4.create(),
      projection: mat4.create(),
      inversProjection: mat4.create(),
    },
  };

  nearestVertexIndex = null;
  smoothRotationVelocity = 0;
  scaleFactor = 1.0;
  movementActive = false;

  constructor(
    canvas,
    items,
    onActiveItemChange,
    onMovementChange,
    onInit = null
  ) {
    this.canvas = canvas;
    this.items = items || [];
    this.onActiveItemChange = onActiveItemChange || (() => {});
    this.onMovementChange = onMovementChange || (() => {});
    this.#init(onInit);
  }

  resize() {
    if (this.isDestroyed || !this.gl) return;

    this.viewportSize = vec2.set(
      this.viewportSize || vec2.create(),
      this.canvas.clientWidth,
      this.canvas.clientHeight
    );

    const gl = this.gl;
    const needsResize = resizeCanvasToDisplaySize(gl.canvas);
    if (needsResize) {
      gl.viewport(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight);
    }

    this.#updateProjectionMatrix(gl);
  }

  isDestroyed = false;
  isRunning = true;
  rafId = null;

  destroy() {
    this.isDestroyed = true;
    this.isRunning = false;
    if (this.rafId) {
      cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
    if (this.control) {
      this.control.destroy();
    }
    if (this.gl) {
      try {
        const gl = this.gl;
        if (this.discProgram) {
          gl.deleteProgram(this.discProgram);
          this.discProgram = null;
        }
        if (this.tex) {
          gl.deleteTexture(this.tex);
          this.tex = null;
        }
        if (this.discVAO) {
          gl.deleteVertexArray(this.discVAO);
          this.discVAO = null;
        }
        if (this.discInstances?.buffer) {
          gl.deleteBuffer(this.discInstances.buffer);
          this.discInstances.buffer = null;
        }
      } catch {
        // ignore WebGL cleanup errors
      }
    }
  }

  pause() {
    this.isRunning = false;
    if (this.rafId) {
      cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
  }

  resume() {
    if (!this.isRunning && !this.isDestroyed) {
      this.isRunning = true;
      this.rafId = requestAnimationFrame((t) => this.run(t));
    }
  }

  run(time = 0) {
    if (!this.isRunning || this.isDestroyed) return;
    this.#deltaTime = Math.min(32, time - this.#time);
    this.#time = time;
    this.#deltaFrames = this.#deltaTime / this.TARGET_FRAME_DURATION;
    this.#frames += this.#deltaFrames;

    this.#animate(this.#deltaTime);
    this.#render();

    this.rafId = requestAnimationFrame((t) => this.run(t));
  }

  #init(onInit) {
    this.gl = this.canvas.getContext('webgl2', {
      antialias: true,
      alpha: false,
      powerPreference: 'high-performance',
    });
    const gl = this.gl;
    if (!gl) {
      throw new Error('No WebGL 2 context!');
    }

    this.viewportSize = vec2.fromValues(
      this.canvas.clientWidth,
      this.canvas.clientHeight
    );
    this.drawBufferSize = vec2.clone(this.viewportSize);

    this.discProgram = createProgram(
      gl,
      [discVertShaderSource, discFragShaderSource],
      null,
      {
        aModelPosition: 0,
        aModelNormal: 1,
        aModelUvs: 2,
        aInstanceMatrix: 3,
      }
    );

    this.discLocations = {
      aModelPosition: gl.getAttribLocation(this.discProgram, 'aModelPosition'),
      aModelUvs: gl.getAttribLocation(this.discProgram, 'aModelUvs'),
      aInstanceMatrix: gl.getAttribLocation(
        this.discProgram,
        'aInstanceMatrix'
      ),
      uWorldMatrix: gl.getUniformLocation(this.discProgram, 'uWorldMatrix'),
      uViewMatrix: gl.getUniformLocation(this.discProgram, 'uViewMatrix'),
      uProjectionMatrix: gl.getUniformLocation(
        this.discProgram,
        'uProjectionMatrix'
      ),
      uCameraPosition: gl.getUniformLocation(
        this.discProgram,
        'uCameraPosition'
      ),
      uScaleFactor: gl.getUniformLocation(this.discProgram, 'uScaleFactor'),
      uRotationAxisVelocity: gl.getUniformLocation(
        this.discProgram,
        'uRotationAxisVelocity'
      ),
      uTex: gl.getUniformLocation(this.discProgram, 'uTex'),
      uFrames: gl.getUniformLocation(this.discProgram, 'uFrames'),
      uItemCount: gl.getUniformLocation(this.discProgram, 'uItemCount'),
      uAtlasSize: gl.getUniformLocation(this.discProgram, 'uAtlasSize'),
    };

    this.discGeo = new DiscGeometry(56, 1);
    this.discBuffers = this.discGeo.data;
    this.discVAO = makeVertexArray(
      gl,
      [
        [
          makeBuffer(gl, this.discBuffers.vertices, gl.STATIC_DRAW),
          this.discLocations.aModelPosition,
          3,
        ],
        [
          makeBuffer(gl, this.discBuffers.uvs, gl.STATIC_DRAW),
          this.discLocations.aModelUvs,
          2,
        ],
      ],
      this.discBuffers.indices
    );

    this.icoGeo = new IcosahedronGeometry();
    this.icoGeo.subdivide(1).spherize(this.SPHERE_RADIUS);
    this.instancePositions = this.icoGeo.vertices.map((v) => v.position);
    this.DISC_INSTANCE_COUNT = this.icoGeo.vertices.length;
    this.#initDiscInstances(this.DISC_INSTANCE_COUNT);

    this.worldMatrix = mat4.create();
    this.#initTexture();

    this.control = new ArcballControl(this.canvas, (deltaTime) =>
      this.#onControlUpdate(deltaTime)
    );

    this.#updateCameraMatrix();
    this.#updateProjectionMatrix(gl);
    this.resize();

    if (onInit) onInit(this);
  }

  #initTexture() {
    const gl = this.gl;
    this.tex = createAndSetupTexture(
      gl,
      gl.LINEAR,
      gl.LINEAR,
      gl.CLAMP_TO_EDGE,
      gl.CLAMP_TO_EDGE
    );

    const itemCount = Math.max(1, this.items.length);
    this.atlasSize = Math.ceil(Math.sqrt(itemCount));
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    const cellSize = 512;

    canvas.width = this.atlasSize * cellSize;
    canvas.height = this.atlasSize * cellSize;

    Promise.all(
      this.items.map(
        (item) =>
          new Promise((resolve) => {
            const img = new Image();
            img.crossOrigin = 'anonymous';
            img.onload = () => resolve(img);
            img.onerror = () => resolve(null);
            img.src = item.image;
          })
      )
    )
      .then((images) => {
        if (this.isDestroyed || !this.gl || !this.tex) return;
        images.forEach((img, i) => {
          if (!img) return;
          const x = (i % this.atlasSize) * cellSize;
          const y = Math.floor(i / this.atlasSize) * cellSize;
          ctx.drawImage(img, x, y, cellSize, cellSize);
        });

        gl.bindTexture(gl.TEXTURE_2D, this.tex);
        gl.texImage2D(
          gl.TEXTURE_2D,
          0,
          gl.RGBA,
          gl.RGBA,
          gl.UNSIGNED_BYTE,
          canvas
        );
        gl.generateMipmap(gl.TEXTURE_2D);
      })
      .catch(() => {
        // ignore load errors if aborted or destroyed
      });
  }

  #initDiscInstances(count) {
    const gl = this.gl;
    this.discInstances = {
      matricesArray: new Float32Array(count * 16),
      matrices: [],
      buffer: gl.createBuffer(),
    };
    for (let i = 0; i < count; ++i) {
      const instanceMatrixArray = new Float32Array(
        this.discInstances.matricesArray.buffer,
        i * 16 * 4,
        16
      );
      instanceMatrixArray.set(mat4.create());
      this.discInstances.matrices.push(instanceMatrixArray);
    }
    gl.bindVertexArray(this.discVAO);
    gl.bindBuffer(gl.ARRAY_BUFFER, this.discInstances.buffer);
    gl.bufferData(
      gl.ARRAY_BUFFER,
      this.discInstances.matricesArray.byteLength,
      gl.DYNAMIC_DRAW
    );
    const mat4AttribSlotCount = 4;
    const bytesPerMatrix = 16 * 4;
    for (let j = 0; j < mat4AttribSlotCount; ++j) {
      const loc = this.discLocations.aInstanceMatrix + j;
      gl.enableVertexAttribArray(loc);
      gl.vertexAttribPointer(
        loc,
        4,
        gl.FLOAT,
        false,
        bytesPerMatrix,
        j * 4 * 4
      );
      gl.vertexAttribDivisor(loc, 1);
    }
    gl.bindBuffer(gl.ARRAY_BUFFER, null);
    gl.bindVertexArray(null);
  }

  #animate(deltaTime) {
    const gl = this.gl;
    this.control.update(deltaTime, this.TARGET_FRAME_DURATION);

    let positions = this.instancePositions.map((p) =>
      vec3.transformQuat(vec3.create(), p, this.control.orientation)
    );
    const scale = 0.25;
    const SCALE_INTENSITY = 0.6;
    positions.forEach((p, ndx) => {
      const s =
        (Math.abs(p[2]) / this.SPHERE_RADIUS) * SCALE_INTENSITY +
        (1 - SCALE_INTENSITY);
      const finalScale = s * scale;
      const matrix = mat4.create();
      mat4.multiply(
        matrix,
        matrix,
        mat4.fromTranslation(mat4.create(), vec3.negate(vec3.create(), p))
      );
      mat4.multiply(
        matrix,
        matrix,
        mat4.targetTo(mat4.create(), [0, 0, 0], p, [0, 1, 0])
      );
      mat4.multiply(
        matrix,
        matrix,
        mat4.fromScaling(mat4.create(), [finalScale, finalScale, finalScale])
      );
      mat4.multiply(
        matrix,
        matrix,
        mat4.fromTranslation(mat4.create(), [0, 0, -this.SPHERE_RADIUS])
      );

      mat4.copy(this.discInstances.matrices[ndx], matrix);
    });

    gl.bindBuffer(gl.ARRAY_BUFFER, this.discInstances.buffer);
    gl.bufferSubData(gl.ARRAY_BUFFER, 0, this.discInstances.matricesArray);
    gl.bindBuffer(gl.ARRAY_BUFFER, null);

    this.smoothRotationVelocity = this.control.rotationVelocity;
  }

  #render() {
    if (this.isDestroyed || !this.gl || !this.tex || !this.discProgram) return;
    const gl = this.gl;
    gl.useProgram(this.discProgram);

    gl.enable(gl.CULL_FACE);
    gl.enable(gl.DEPTH_TEST);

    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);

    gl.uniformMatrix4fv(
      this.discLocations.uWorldMatrix,
      false,
      this.worldMatrix
    );
    gl.uniformMatrix4fv(
      this.discLocations.uViewMatrix,
      false,
      this.camera.matrices.view
    );
    gl.uniformMatrix4fv(
      this.discLocations.uProjectionMatrix,
      false,
      this.camera.matrices.projection
    );
    gl.uniform3f(
      this.discLocations.uCameraPosition,
      this.camera.position[0],
      this.camera.position[1],
      this.camera.position[2]
    );
    gl.uniform4f(
      this.discLocations.uRotationAxisVelocity,
      this.control.rotationAxis[0],
      this.control.rotationAxis[1],
      this.control.rotationAxis[2],
      this.smoothRotationVelocity * 1.1
    );

    gl.uniform1i(this.discLocations.uItemCount, this.items.length);
    gl.uniform1i(this.discLocations.uAtlasSize, this.atlasSize);

    gl.uniform1f(this.discLocations.uFrames, this.#frames);
    gl.uniform1f(this.discLocations.uScaleFactor, this.scaleFactor);
    gl.uniform1i(this.discLocations.uTex, 0);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, this.tex);

    gl.bindVertexArray(this.discVAO);
    gl.drawElementsInstanced(
      gl.TRIANGLES,
      this.discBuffers.indices.length,
      gl.UNSIGNED_SHORT,
      0,
      this.DISC_INSTANCE_COUNT
    );
  }

  #updateCameraMatrix() {
    mat4.targetTo(
      this.camera.matrix,
      this.camera.position,
      [0, 0, 0],
      this.camera.up
    );
    mat4.invert(this.camera.matrices.view, this.camera.matrix);
  }

  #updateProjectionMatrix(gl) {
    const width = gl.canvas.clientWidth || 300;
    const height = gl.canvas.clientHeight || 300;
    this.camera.aspect = width / height;
    const sphereHeight = this.SPHERE_RADIUS * 0.35;
    const distance = this.camera.position[2];
    if (this.camera.aspect > 1) {
      this.camera.fov = 2 * Math.atan(sphereHeight / distance);
    } else {
      this.camera.fov =
        2 *
        Math.atan(
          (sphereHeight * 1.15) / Math.max(0.4, this.camera.aspect) / distance
        );
    }
    mat4.perspective(
      this.camera.matrices.projection,
      this.camera.fov,
      this.camera.aspect,
      this.camera.near,
      this.camera.far
    );
    mat4.invert(
      this.camera.matrices.inversProjection,
      this.camera.matrices.projection
    );
  }

  selectItem(index) {
    if (!this.items.length || !this.instancePositions?.length) return;
    const count = this.items.length;
    const targetIdx = ((index % count) + count) % count;

    const n = this.control.snapDirection;
    const inversOrientation = quat.conjugate(
      quat.create(),
      this.control.orientation
    );
    const nt = vec3.transformQuat(vec3.create(), n, inversOrientation);

    let maxD = -Infinity;
    let targetVertexIndex = -1;
    for (let i = 0; i < this.instancePositions.length; ++i) {
      if (i % count === targetIdx) {
        const d = vec3.dot(nt, this.instancePositions[i]);
        if (d > maxD) {
          maxD = d;
          targetVertexIndex = i;
        }
      }
    }

    if (targetVertexIndex !== -1) {
      const targetPos = this.instancePositions[targetVertexIndex];
      const currentPosInWorld = vec3.transformQuat(
        vec3.create(),
        targetPos,
        this.control.orientation
      );
      vec3.normalize(currentPosInWorld, currentPosInWorld);
      const rot = quat.create();
      this.control.quatFromVectors(
        currentPosInWorld,
        this.control.snapDirection,
        rot,
        1
      );
      quat.multiply(this.control.orientation, rot, this.control.orientation);
      quat.normalize(this.control.orientation, this.control.orientation);
      this.onActiveItemChange(targetIdx);
    }
  }

  #onControlUpdate(deltaTime) {
    const timeScale = deltaTime / this.TARGET_FRAME_DURATION + 0.0001;
    let damping = 5 / timeScale;
    let cameraTargetZ = 3;

    const isMoving =
      this.control.isPointerDown ||
      Math.abs(this.smoothRotationVelocity) > 0.01;

    if (isMoving !== this.movementActive) {
      this.movementActive = isMoving;
      this.onMovementChange(isMoving);
    }

    if (!this.control.isPointerDown) {
      const nearestVertexIndex = this.#findNearestVertexIndex();
      const itemIndex = nearestVertexIndex % Math.max(1, this.items.length);
      this.onActiveItemChange(itemIndex);
      const snapDirection = vec3.normalize(
        vec3.create(),
        this.#getVertexWorldPosition(nearestVertexIndex)
      );
      this.control.snapTargetDirection = snapDirection;
    } else {
      cameraTargetZ += this.control.rotationVelocity * 80 + 2.5;
      damping = 7 / timeScale;
    }

    this.camera.position[2] +=
      (cameraTargetZ - this.camera.position[2]) / damping;
    this.#updateCameraMatrix();
  }

  #findNearestVertexIndex() {
    const n = this.control.snapDirection;
    const inversOrientation = quat.conjugate(
      quat.create(),
      this.control.orientation
    );
    const nt = vec3.transformQuat(vec3.create(), n, inversOrientation);

    let maxD = -1;
    let nearestVertexIndex;
    for (let i = 0; i < this.instancePositions.length; ++i) {
      const d = vec3.dot(nt, this.instancePositions[i]);
      if (d > maxD) {
        maxD = d;
        nearestVertexIndex = i;
      }
    }
    return nearestVertexIndex;
  }

  #getVertexWorldPosition(index) {
    const nearestVertexPos = this.instancePositions[index];
    return vec3.transformQuat(
      vec3.create(),
      nearestVertexPos,
      this.control.orientation
    );
  }
}

const defaultItems = [
  {
    image: 'https://picsum.photos/900/900?grayscale',
    link: 'https://google.com/',
    title: '',
    description: '',
  },
];

export default function InfiniteMenu({ items = [] }) {
  const containerRef = useRef(null);
  const canvasRef = useRef(null);
  const sketchRef = useRef(null);
  const [activeItem, setActiveItem] = useState(null);
  const [activeIndex, setActiveIndex] = useState(0);
  const [isMoving, setIsMoving] = useState(false);
  const [hasWebGlError, setHasWebGlError] = useState(false);
  const [hasInteracted, setHasInteracted] = useState(false);

  const safeItems = useMemo(
    () => (items && items.length ? items : defaultItems),
    [items]
  );

  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    let sketch = null;
    let observer = null;
    let resizeObserver = null;

    const handleActiveItem = (index) => {
      const itemIndex =
        ((index % safeItems.length) + safeItems.length) % safeItems.length;
      setActiveIndex(itemIndex);
      setActiveItem(safeItems[itemIndex]);
    };

    const handleMovement = (moving) => {
      if (moving) setHasInteracted(true);
      setIsMoving(moving);
    };

    if (canvas) {
      try {
        sketch = new InfiniteGridMenu(
          canvas,
          safeItems,
          handleActiveItem,
          handleMovement,
          (sk) => sk.run()
        );
        sketchRef.current = sketch;
      } catch (err) {
        console.warn(
          'WebGL2 not supported or failed to initialize, using fallback:',
          err
        );
        setHasWebGlError(true);
      }
    }

    const handleResize = () => {
      if (sketch) {
        sketch.resize();
      }
    };

    window.addEventListener('resize', handleResize, { passive: true });
    window.addEventListener('orientationchange', handleResize, {
      passive: true,
    });
    handleResize();

    // ResizeObserver for dynamic layout changes and mobile toolbar transitions
    if (container && typeof ResizeObserver !== 'undefined') {
      resizeObserver = new ResizeObserver(() => {
        handleResize();
      });
      resizeObserver.observe(container);
    }

    // Auto-pause WebGL render loop when scrolled off-screen
    if (container && sketch) {
      observer = new IntersectionObserver(
        ([entry]) => {
          if (entry.isIntersecting) {
            sketch?.resume();
          } else {
            sketch?.pause();
          }
        },
        { threshold: 0.05 }
      );
      observer.observe(container);
    }

    const handleContextLost = (e) => {
      e.preventDefault();
      sketch?.pause();
      setHasWebGlError(true);
    };

    const handleContextRestored = () => {
      setHasWebGlError(false);
      sketch?.resume();
    };

    if (canvas) {
      canvas.addEventListener('webglcontextlost', handleContextLost, false);
      canvas.addEventListener(
        'webglcontextrestored',
        handleContextRestored,
        false
      );
    }

    return () => {
      observer?.disconnect();
      resizeObserver?.disconnect();
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('orientationchange', handleResize);
      if (canvas) {
        canvas.removeEventListener('webglcontextlost', handleContextLost);
        canvas.removeEventListener(
          'webglcontextrestored',
          handleContextRestored
        );
      }
      sketch?.destroy();
      sketchRef.current = null;
    };
  }, [safeItems]);

  const handleSelect = (index) => {
    setHasInteracted(true);
    const itemIndex =
      ((index % safeItems.length) + safeItems.length) % safeItems.length;
    setActiveIndex(itemIndex);
    setActiveItem(safeItems[itemIndex]);
    sketchRef.current?.selectItem(itemIndex);
  };

  const handleButtonClick = () => {
    const current = activeItem || safeItems[activeIndex] || safeItems[0];
    if (!current?.link) return;
    if (current.link.startsWith('http')) {
      window.open(current.link, '_blank', 'noopener,noreferrer');
    } else {
      window.location.href = current.link;
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
      e.preventDefault();
      handleSelect(activeIndex + 1);
    } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
      e.preventDefault();
      handleSelect(activeIndex - 1);
    }
  };

  const currentActive = activeItem || safeItems[activeIndex] || safeItems[0];

  if (hasWebGlError) {
    return (
      <div
        ref={containerRef}
        className="relative w-full h-full min-h-[480px] sm:min-h-[540px] md:min-h-[600px] flex flex-col items-center justify-center p-4 text-white"
      >
        <div className="w-full max-w-xl bg-white/[0.04] border border-white/10 rounded-3xl p-6 md:p-8 backdrop-blur-md shadow-2xl flex flex-col items-center text-center">
          <div className="flex flex-wrap justify-center gap-2 mb-6">
            {safeItems.map((item, idx) => (
              <button
                key={item.title || idx}
                onClick={() => handleSelect(idx)}
                className={`px-3.5 py-1.5 rounded-full text-xs sm:text-sm font-medium transition-all ${
                  activeIndex === idx
                    ? 'bg-white text-black shadow-md'
                    : 'bg-white/10 text-white/70 hover:bg-white/20 hover:text-white'
                }`}
              >
                {item.title}
              </button>
            ))}
          </div>

          <div className="w-24 h-24 sm:w-28 sm:h-28 rounded-full overflow-hidden border-2 border-white/20 mb-4 shadow-lg">
            <img
              src={currentActive.image}
              alt={currentActive.title}
              className="w-full h-full object-cover"
            />
          </div>

          <h3 className="text-2xl sm:text-3xl font-black mb-2">
            {currentActive.title}
          </h3>
          <p className="text-sm sm:text-base text-white/70 max-w-sm mb-6">
            {currentActive.description}
          </p>

          <button
            onClick={handleButtonClick}
            className="flex items-center gap-2 px-6 py-3 rounded-full bg-red-600 hover:bg-red-500 text-white font-bold text-sm sm:text-base transition-transform active:scale-95 shadow-lg shadow-red-600/30"
          >
            Visit {currentActive.title}
            <span aria-hidden="true">&#x2197;</span>
          </button>
        </div>
      </div>
    );
  }

  return (
    <div
      ref={containerRef}
      tabIndex={0}
      onKeyDown={handleKeyDown}
      className="relative w-full h-full min-h-[480px] sm:min-h-[540px] md:min-h-[600px] flex items-center justify-center select-none overflow-hidden outline-none"
      aria-label="Interactive 3D Social Media Menu. Swipe or use arrow keys to navigate."
    >
      {/* Quick Select Navigation Chips */}
      <nav
        aria-label="Social media channels"
        className="absolute top-3 sm:top-5 left-1/2 -translate-x-1/2 z-20 flex items-center gap-1.5 sm:gap-2 px-2.5 sm:px-3 py-1 sm:py-1.5 rounded-full bg-black/60 backdrop-blur-md border border-white/15 max-w-[95vw] overflow-x-auto shadow-lg"
      >
        {safeItems.map((item, idx) => (
          <button
            key={item.title || idx}
            type="button"
            onClick={() => handleSelect(idx)}
            className={`px-2.5 sm:px-3 py-1 rounded-full text-xs sm:text-sm font-medium transition-all duration-200 whitespace-nowrap focus-visible:outline-white ${
              activeIndex === idx
                ? 'bg-white text-black font-semibold shadow-sm scale-105'
                : 'text-white/70 hover:text-white hover:bg-white/10'
            }`}
            aria-selected={activeIndex === idx}
            aria-label={`Select ${item.title}`}
          >
            {item.title}
          </button>
        ))}
      </nav>

      <canvas
        id="infinite-grid-menu-canvas"
        ref={canvasRef}
        style={{ touchAction: 'pan-y' }}
        className="cursor-grab w-full h-full overflow-hidden absolute inset-0 outline-none active:cursor-grabbing"
      />

      {currentActive && (
        <>
          {/* Responsive Title */}
          <h2
            className={`
              select-none
              absolute
              font-black
              text-white
              pointer-events-none
              z-10
              left-4 sm:left-6 md:left-8 lg:left-14 xl:left-20
              top-14 sm:top-16 md:top-1/2
              md:-translate-y-1/2
              text-2xl sm:text-3xl md:text-5xl lg:text-6xl xl:text-7xl
              tracking-tight
              drop-shadow-lg
              transition-all
              ease-[cubic-bezier(0.25,0.1,0.25,1.0)]
              ${
                isMoving
                  ? 'opacity-0 scale-95 duration-100'
                  : 'opacity-100 scale-100 duration-500'
              }
            `}
          >
            {currentActive.title}
          </h2>

          {/* Responsive Description */}
          <p
            className={`
              select-none
              absolute
              text-white/80
              pointer-events-none
              z-10
              text-right
              right-4 sm:right-6 md:right-8 lg:right-14 xl:right-20
              top-14 sm:top-16 md:top-1/2
              md:-translate-y-1/2
              text-xs sm:text-sm md:text-base lg:text-lg xl:text-xl
              max-w-[14ch] sm:max-w-[18ch] md:max-w-[22ch] lg:max-w-[26ch]
              drop-shadow-md
              transition-all
              ease-[cubic-bezier(0.25,0.1,0.25,1.0)]
              ${
                isMoving
                  ? 'opacity-0 scale-95 duration-100'
                  : 'opacity-100 scale-100 duration-500'
              }
            `}
          >
            {currentActive.description}
          </p>

          {/* Gesture hint */}
          {!hasInteracted && (
            <div
              className={`
                absolute
                bottom-20 sm:bottom-24
                left-1/2
                -translate-x-1/2
                z-10
                pointer-events-none
                text-white/40
                text-[10px] sm:text-xs
                tracking-wider
                uppercase
                font-mono
                bg-black/40
                backdrop-blur-xs
                px-3 py-1
                rounded-full
                border border-white/10
                flex items-center gap-1.5
                animate-pulse
                transition-opacity duration-300
                ${isMoving ? 'opacity-0' : 'opacity-100'}
              `}
            >
              <span>⟵ Drag to rotate ⟶</span>
            </div>
          )}

          {/* Responsive Action Button */}
          <div
            role="link"
            tabIndex={0}
            onClick={handleButtonClick}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                handleButtonClick();
              }
            }}
            aria-label={`Open ${currentActive.title} in new tab`}
            className={`
              absolute
              left-1/2
              z-20
              bottom-4 sm:bottom-6 md:bottom-8
              w-12 h-12 sm:w-14 sm:h-14 md:w-16 md:h-16 lg:w-20 lg:h-20
              grid place-items-center
              bg-[#ff0000]
              border-4 md:border-[6px] lg:border-[8px] border-black
              rounded-full
              cursor-pointer
              shadow-xl
              hover:scale-110 active:scale-95
              focus-visible:ring-4 focus-visible:ring-white focus-visible:outline-none
              transition-all duration-300 ease-[cubic-bezier(0.25,0.1,0.25,1.0)]
              ${
                isMoving
                  ? 'scale-0 opacity-0 pointer-events-none -translate-x-1/2'
                  : 'scale-100 opacity-100 pointer-events-auto -translate-x-1/2'
              }
            `}
          >
            <span
              className="select-none relative text-[#060010] font-black text-lg sm:text-xl md:text-2xl lg:text-3xl leading-none"
              aria-hidden="true"
            >
              &#x2197;
            </span>
          </div>
        </>
      )}
    </div>
  );
}
